#!/usr/bin/env node
/*
 * REATIVACAO DE LEADS PERDIDOS - Studio Realcar
 *
 * Nova tela em Marketing > "Reativar perdidos":
 *  - lista quem esta como Perdido, tem telefone, nunca recebeu e nao tem
 *    horario marcado; filtros por servico, data da perda e origem; paginada;
 *  - mensagem pronta com o nome e o servico (texto editavel por servico e
 *    tambem antes de cada envio);
 *  - cada pessoa recebe UMA vez (mesmo telefone em outro cadastro fica travado);
 *  - limite por dia ("hoje voce enviou X de Y") e pausa de 30s entre envios;
 *  - aba "Ja enviadas" com o resultado (respondeu / agendou / sem resposta);
 *    quem agendou depois da mensagem e percebido sozinho.
 *
 * Cria 4 colunas em Lead e 1 na configuracao (migracao automatica no deploy).
 * Precisa ter rodado antes o clique-provavel-e-mesmo-clique.mjs.
 * Pode rodar mais de uma vez; se algum trecho nao for encontrado, NADA e gravado.
 *
 * Uso: node reativacao-perdidos.mjs
 */
import fs from "node:fs";
import path from "node:path";

const DATA = {"novosArquivos":{"lib/reativacao-perdidos.ts":"/**\n * Reativacao de leads perdidos (\"ultima mensagem\").\n *\n * Regras:\n *  - entra quem esta como Perdido, tem telefone e nunca recebeu a mensagem de\n *    reativacao (cada pessoa recebe UMA vez so);\n *  - sai quem ja tem horario marcado para frente;\n *  - o envio e feito a mao, um por um, com limite por dia e uma pausa curta\n *    entre um envio e outro (protege o numero do WhatsApp).\n */\n\nexport const CATEGORIA_REATIVACAO_PERDIDOS = \"Reativação de perdidos\";\nexport const PREFIXO_MODELO = \"reativacao-perdido:\";\nexport const CHAVE_MODELO_PADRAO = `${PREFIXO_MODELO}padrao`;\nexport const POR_PAGINA = 30;\nexport const PAUSA_ENTRE_ENVIOS_SEGUNDOS = 30;\nexport const LIMITE_MINIMO = 1;\nexport const LIMITE_MAXIMO = 60;\n\nexport type ResultadoReativacao = \"RESPONDEU\" | \"AGENDOU\" | \"SEM_RESPOSTA\";\n\nexport const ROTULO_RESULTADO: Record<ResultadoReativacao, string> = {\n  RESPONDEU: \"Respondeu\",\n  AGENDOU: \"Agendou / voltou\",\n  SEM_RESPOSTA: \"Sem resposta\",\n};\n\nexport const TEXTO_PADRAO =\n  \"Oi, {nome}! Tudo bem? 😊 Aqui é do Studio Realçar.\\n\\n\" +\n  \"Um tempo atrás você falou com a gente sobre {servico}. Ainda tem interesse?\\n\\n\" +\n  \"Estamos com horários nesta semana e posso reservar um para você. Me conta qual dia e período (manhã ou tarde) ficam melhores. 💜\";\n\nexport function normalizarTexto(valor?: string | null) {\n  return (valor || \"\")\n    .normalize(\"NFD\")\n    .replace(/[̀-ͯ]/g, \"\")\n    .replace(/\\s+/g, \" \")\n    .trim()\n    .toLowerCase();\n}\n\nexport function chaveModeloDoServico(servico: string | null) {\n  const normal = normalizarTexto(servico);\n  return normal ? `${PREFIXO_MODELO}${normal}` : CHAVE_MODELO_PADRAO;\n}\n\nexport function primeiroNome(nome?: string | null) {\n  const limpo = (nome || \"\").trim();\n  if (!limpo || /^contato via an[uú]ncio/i.test(limpo)) return \"\";\n  return limpo.split(/\\s+/)[0];\n}\n\n/** Troca {nome} e {servico} no texto do modelo. */\nexport function montarMensagem(modelo: string, dados: { nome?: string | null; servico?: string | null }) {\n  const nome = primeiroNome(dados.nome);\n  const servico = (dados.servico || \"\").trim().toLowerCase() || \"nossos tratamentos\";\n  return modelo\n    .replace(/\\{nome\\}/gi, nome)\n    .replace(/Oi, !/g, \"Oi!\")\n    .replace(/Olá, !/g, \"Olá!\")\n    .replace(/\\{servico\\}|\\{serviço\\}/gi, servico)\n    .trim();\n}\n\nconst PALAVRAS_FRACAS = new Set([\"contato\", \"via\", \"anuncio\", \"de\", \"da\", \"do\", \"e\", \"com\", \"para\", \"a\", \"o\"]);\n\nfunction primeiraPalavraForte(texto: string) {\n  return texto.split(\" \").find((palavra) => palavra.length >= 4 && !PALAVRAS_FRACAS.has(palavra)) || \"\";\n}\n\n/**\n * Descobre o \"servico\" de um interesse escrito livre (\"limpeza\", \"Limpeza de\n * pele luxo\", \"Contato via anuncio · Criolipolise\") usando a lista de servicos\n * cadastrados. Sem servico parecido, fica o proprio texto.\n */\nexport function servicoDoInteresse(interesse: string | null | undefined, servicos: string[]): string | null {\n  const bruto = (interesse || \"\").replace(/^contato via an[uú]ncio\\s*[·\\-:]?\\s*/i, \"\").trim();\n  const alvo = normalizarTexto(bruto);\n  if (!alvo) return null;\n\n  const lista = servicos\n    .map((nome) => ({ nome, normal: normalizarTexto(nome) }))\n    .filter((item) => item.normal);\n\n  const exato = lista.find((item) => item.normal === alvo);\n  if (exato) return exato.nome;\n\n  // Servico escrito dentro do interesse (\"quero limpeza de pele luxo\"): o mais completo.\n  const dentroDoInteresse = lista\n    .filter((item) => alvo.includes(item.normal))\n    .sort((a, b) => b.normal.length - a.normal.length);\n  if (dentroDoInteresse.length > 0) return dentroDoInteresse[0].nome;\n\n  // Interesse curto dentro do nome do servico (\"limpeza\"): o mais simples.\n  const interesseDentro = lista\n    .filter((item) => item.normal.includes(alvo))\n    .sort((a, b) => a.normal.length - b.normal.length);\n  if (interesseDentro.length > 0) return interesseDentro[0].nome;\n\n  const palavra = primeiraPalavraForte(alvo);\n  if (palavra) {\n    const porPalavra = lista\n      .filter((item) => primeiraPalavraForte(item.normal) === palavra)\n      .sort((a, b) => a.normal.length - b.normal.length);\n    if (porPalavra.length > 0) return porPalavra[0].nome;\n  }\n\n  return bruto.charAt(0).toUpperCase() + bruto.slice(1);\n}\n\n/** Inicio do dia de hoje no horario de Brasilia. */\nexport function inicioDoDiaSaoPaulo(agora: Date = new Date()) {\n  const dia = new Intl.DateTimeFormat(\"en-CA\", {\n    timeZone: \"America/Sao_Paulo\",\n    year: \"numeric\",\n    month: \"2-digit\",\n    day: \"2-digit\",\n  }).format(agora);\n  return new Date(`${dia}T00:00:00-03:00`);\n}\n\nexport function somenteDigitos(valor?: string | null) {\n  const digitos = (valor || \"\").replace(/\\D/g, \"\");\n  // Ignora o 55 do Brasil para comparar o mesmo numero escrito de jeitos diferentes.\n  return digitos.length > 11 && digitos.startsWith(\"55\") ? digitos.slice(2) : digitos;\n}\n","lib/reativacao-perdidos-dados.ts":"import type { Prisma } from \"@prisma/client\";\n\nimport { prisma } from \"@/lib/prisma\";\nimport {\n  CATEGORIA_REATIVACAO_PERDIDOS,\n  CHAVE_MODELO_PADRAO,\n  POR_PAGINA,\n  PREFIXO_MODELO,\n  TEXTO_PADRAO,\n  chaveModeloDoServico,\n  inicioDoDiaSaoPaulo,\n  montarMensagem,\n  servicoDoInteresse,\n  somenteDigitos,\n  type ResultadoReativacao,\n} from \"@/lib/reativacao-perdidos\";\n\nexport const SEM_SERVICO = \"Sem serviço informado\";\n\nexport type FiltrosReativacao = {\n  aba: \"lista\" | \"enviadas\";\n  servico: string;\n  dias: number; // 0 = qualquer data\n  origem: string;\n  pagina: number;\n};\n\nexport type ItemReativacao = {\n  id: number;\n  nome: string;\n  telefone: string;\n  servico: string | null;\n  origem: string | null;\n  motivoPerda: string | null;\n  perdidoEm: string | null;\n  mensagem: string;\n  // Mesmo telefone de alguem que ja recebeu (outro cadastro da mesma pessoa).\n  jaRecebeuPorOutroCadastro: boolean;\n};\n\nexport type ItemEnviado = {\n  id: number;\n  nome: string;\n  telefone: string | null;\n  servico: string | null;\n  enviadaEm: string;\n  resultado: ResultadoReativacao | null;\n  // Agendou depois da mensagem (o sistema percebe sozinho).\n  agendouSozinho: boolean;\n  etapa: string;\n  clienteId: number | null;\n};\n\nexport type DadosReativacao = {\n  filtros: FiltrosReativacao;\n  servicos: Array<{ nome: string; quantidade: number }>;\n  origens: Array<{ nome: string; quantidade: number }>;\n  totalLista: number;\n  itens: ItemReativacao[];\n  totalEnviadas: number;\n  enviadas: ItemEnviado[];\n  resumo: { enviadas: number; responderam: number; voltaram: number; enviadasHoje: number };\n  limiteDiario: number;\n  ultimoEnvioEm: string | null;\n  modelos: Array<{ servico: string | null; chave: string; texto: string; personalizado: boolean }>;\n};\n\nfunction lerNumero(valor: string | undefined, padrao: number) {\n  const numero = Number(valor);\n  return Number.isFinite(numero) ? numero : padrao;\n}\n\nexport function lerFiltros(params: Record<string, string | undefined>): FiltrosReativacao {\n  const dias = lerNumero(params.dias, 0);\n  return {\n    aba: params.aba === \"enviadas\" ? \"enviadas\" : \"lista\",\n    servico: (params.servico || \"\").trim(),\n    dias: [0, 30, 60, 90, 180, 365].includes(dias) ? dias : 0,\n    origem: (params.origem || \"\").trim(),\n    pagina: Math.max(1, Math.floor(lerNumero(params.pagina, 1))),\n  };\n}\n\nexport async function carregarReativacao(filtros: FiltrosReativacao): Promise<DadosReativacao> {\n  const agora = new Date();\n\n  // Quem pode receber: perdido, com telefone, nunca recebeu e sem horario marcado.\n  const base: Prisma.LeadWhereInput = {\n    etapa: \"Perdido\",\n    reativacaoEnviadaEm: null,\n    telefone: { not: null },\n    NOT: [\n      { telefone: \"\" },\n      {\n        cliente: {\n          is: { agendamentos: { some: { data: { gt: agora }, status: { notIn: [\"Cancelado\", \"Faltou\"] } } } },\n        },\n      },\n    ],\n  };\n\n  const [servicosCadastrados, porInteresse, porOrigem, config, enviadasHoje, ultimoEnvio, modelosSalvos] =\n    await Promise.all([\n      prisma.procedimentoServico.findMany({ select: { nome: true } }),\n      prisma.lead.groupBy({ by: [\"interesse\"], where: base, _count: { _all: true } }),\n      prisma.lead.groupBy({ by: [\"origem\"], where: base, _count: { _all: true } }),\n      prisma.configuracaoClinica.findFirst({ select: { reativacaoLimiteDiario: true } }),\n      prisma.comunicacaoRegistro.count({\n        where: { categoria: CATEGORIA_REATIVACAO_PERDIDOS, enviadoEm: { gte: inicioDoDiaSaoPaulo(agora) } },\n      }),\n      prisma.comunicacaoRegistro.findFirst({\n        where: { categoria: CATEGORIA_REATIVACAO_PERDIDOS },\n        orderBy: { enviadoEm: \"desc\" },\n        select: { enviadoEm: true },\n      }),\n      prisma.mensagemModelo.findMany({\n        where: { chave: { startsWith: PREFIXO_MODELO } },\n        select: { chave: true, nome: true, corpo: true },\n      }),\n    ]);\n\n  const nomesServicos = servicosCadastrados.map((item) => item.nome);\n\n  // Agrupa os interesses escritos de jeitos diferentes no mesmo servico.\n  const brutosPorServico = new Map<string, Array<string | null>>();\n  const quantidadePorServico = new Map<string, number>();\n  for (const grupo of porInteresse) {\n    const servico = servicoDoInteresse(grupo.interesse, nomesServicos) ?? SEM_SERVICO;\n    brutosPorServico.set(servico, [...(brutosPorServico.get(servico) ?? []), grupo.interesse]);\n    quantidadePorServico.set(servico, (quantidadePorServico.get(servico) ?? 0) + grupo._count._all);\n  }\n  const servicos = Array.from(quantidadePorServico.entries())\n    .map(([nome, quantidade]) => ({ nome, quantidade }))\n    .sort((a, b) => b.quantidade - a.quantidade || a.nome.localeCompare(b.nome, \"pt-BR\"));\n\n  const origens = porOrigem\n    .map((grupo) => ({ nome: grupo.origem || \"Sem origem\", quantidade: grupo._count._all }))\n    .sort((a, b) => b.quantidade - a.quantidade);\n\n  // Filtros escolhidos na tela (tudo resolvido no banco).\n  const filtrosLista: Prisma.LeadWhereInput[] = [base];\n  if (filtros.servico) {\n    const brutos = brutosPorServico.get(filtros.servico) ?? [];\n    const comTexto = brutos.filter((item): item is string => Boolean(item));\n    filtrosLista.push({\n      OR: [\n        ...(comTexto.length > 0 ? [{ interesse: { in: comTexto } }] : []),\n        ...(brutos.includes(null) ? [{ interesse: null }] : []),\n        ...(brutos.length === 0 ? [{ id: -1 }] : []),\n      ],\n    });\n  }\n  if (filtros.dias > 0) {\n    filtrosLista.push({ perdidoEm: { gte: new Date(agora.getTime() - filtros.dias * 86_400_000) } });\n  }\n  if (filtros.origem) {\n    filtrosLista.push(filtros.origem === \"Sem origem\" ? { origem: null } : { origem: filtros.origem });\n  }\n  const whereLista: Prisma.LeadWhereInput = { AND: filtrosLista };\n\n  // Modelos de texto: um por servico (ou o padrao).\n  const modeloPorChave = new Map(modelosSalvos.map((item) => [item.chave, item.corpo]));\n  const textoDoServico = (servico: string | null) =>\n    modeloPorChave.get(chaveModeloDoServico(servico)) ?? modeloPorChave.get(CHAVE_MODELO_PADRAO) ?? TEXTO_PADRAO;\n\n  // Telefones de quem ja recebeu (para nao mandar de novo por outro cadastro).\n  const jaEnviados = await prisma.lead.findMany({\n    where: { reativacaoEnviadaEm: { not: null } },\n    select: {\n      id: true,\n      nome: true,\n      telefone: true,\n      interesse: true,\n      etapa: true,\n      clienteId: true,\n      reativacaoEnviadaEm: true,\n      reativacaoResultado: true,\n    },\n    orderBy: { reativacaoEnviadaEm: \"desc\" },\n  });\n  const telefonesEnviados = new Set(jaEnviados.map((item) => somenteDigitos(item.telefone)).filter(Boolean));\n\n  const [totalLista, pagina] = await Promise.all([\n    prisma.lead.count({ where: whereLista }),\n    filtros.aba === \"lista\"\n      ? prisma.lead.findMany({\n          where: whereLista,\n          orderBy: [{ perdidoEm: { sort: \"desc\", nulls: \"last\" } }, { id: \"desc\" }],\n          skip: (filtros.pagina - 1) * POR_PAGINA,\n          take: POR_PAGINA,\n          select: { id: true, nome: true, telefone: true, interesse: true, origem: true, motivoPerda: true, perdidoEm: true },\n        })\n      : Promise.resolve([]),\n  ]);\n\n  const vistosNaPagina = new Set<string>();\n  const itens: ItemReativacao[] = pagina.map((lead) => {\n    const servico = servicoDoInteresse(lead.interesse, nomesServicos);\n    const digitos = somenteDigitos(lead.telefone);\n    const repetido = Boolean(digitos) && (telefonesEnviados.has(digitos) || vistosNaPagina.has(digitos));\n    if (digitos) vistosNaPagina.add(digitos);\n    return {\n      id: lead.id,\n      nome: lead.nome,\n      telefone: lead.telefone || \"\",\n      servico,\n      origem: lead.origem,\n      motivoPerda: lead.motivoPerda,\n      perdidoEm: lead.perdidoEm?.toISOString() ?? null,\n      mensagem: montarMensagem(textoDoServico(servico), { nome: lead.nome, servico }),\n      jaRecebeuPorOutroCadastro: repetido,\n    };\n  });\n\n  // Resultado: quem agendou depois da mensagem (o sistema percebe sozinho).\n  const clienteIds = Array.from(new Set(jaEnviados.map((item) => item.clienteId).filter((id): id is number => Boolean(id))));\n  const maisAntigo = jaEnviados.at(-1)?.reativacaoEnviadaEm ?? agora;\n  const agendamentosDepois = clienteIds.length\n    ? await prisma.agendamento.findMany({\n        where: { clienteId: { in: clienteIds }, createdAt: { gte: maisAntigo }, status: { not: \"Cancelado\" } },\n        select: { clienteId: true, createdAt: true },\n      })\n    : [];\n\n  const enviadasTodas: ItemEnviado[] = jaEnviados.map((lead) => {\n    const enviadaEm = lead.reativacaoEnviadaEm as Date;\n    const agendouSozinho =\n      [\"Agendado\", \"Convertido\"].includes(lead.etapa) ||\n      agendamentosDepois.some((item) => item.clienteId === lead.clienteId && item.createdAt > enviadaEm);\n    return {\n      id: lead.id,\n      nome: lead.nome,\n      telefone: lead.telefone,\n      servico: servicoDoInteresse(lead.interesse, nomesServicos),\n      enviadaEm: enviadaEm.toISOString(),\n      resultado: (lead.reativacaoResultado as ResultadoReativacao | null) ?? null,\n      agendouSozinho,\n      etapa: lead.etapa,\n      clienteId: lead.clienteId,\n    };\n  });\n\n  const voltaram = enviadasTodas.filter((item) => item.resultado === \"AGENDOU\" || item.agendouSozinho).length;\n  const responderam = enviadasTodas.filter(\n    (item) => item.resultado === \"RESPONDEU\" || item.resultado === \"AGENDOU\" || item.agendouSozinho,\n  ).length;\n\n  const servicosDosModelos = new Set<string | null>([null, ...servicos.map((item) => (item.nome === SEM_SERVICO ? null : item.nome))]);\n  const modelos = Array.from(servicosDosModelos).map((servico) => {\n    const chave = chaveModeloDoServico(servico);\n    return {\n      servico,\n      chave,\n      texto: modeloPorChave.get(chave) ?? (servico ? textoDoServico(null) : TEXTO_PADRAO),\n      personalizado: modeloPorChave.has(chave),\n    };\n  });\n\n  return {\n    filtros,\n    servicos,\n    origens,\n    totalLista,\n    itens,\n    totalEnviadas: enviadasTodas.length,\n    enviadas:\n      filtros.aba === \"enviadas\"\n        ? enviadasTodas.slice((filtros.pagina - 1) * POR_PAGINA, filtros.pagina * POR_PAGINA)\n        : [],\n    resumo: { enviadas: enviadasTodas.length, responderam, voltaram, enviadasHoje },\n    limiteDiario: config?.reativacaoLimiteDiario ?? 15,\n    ultimoEnvioEm: ultimoEnvio?.enviadoEm?.toISOString() ?? null,\n    modelos,\n  };\n}\n","actions/reativacao-perdidos.actions.ts":"\"use server\";\n\nimport { revalidatePath } from \"next/cache\";\n\nimport { requirePermission } from \"@/lib/auth\";\nimport { prisma } from \"@/lib/prisma\";\nimport {\n  CATEGORIA_REATIVACAO_PERDIDOS,\n  LIMITE_MAXIMO,\n  LIMITE_MINIMO,\n  ROTULO_RESULTADO,\n  chaveModeloDoServico,\n  inicioDoDiaSaoPaulo,\n  type ResultadoReativacao,\n} from \"@/lib/reativacao-perdidos\";\n\nfunction revalidar() {\n  revalidatePath(\"/marketing/reativacao\");\n  revalidatePath(\"/marketing\");\n  revalidatePath(\"/comunicacoes\");\n}\n\nasync function limiteDiario() {\n  const config = await prisma.configuracaoClinica.findFirst({ select: { reativacaoLimiteDiario: true } });\n  return config?.reativacaoLimiteDiario ?? 15;\n}\n\nasync function enviadasHoje() {\n  return prisma.comunicacaoRegistro.count({\n    where: { categoria: CATEGORIA_REATIVACAO_PERDIDOS, enviadoEm: { gte: inicioDoDiaSaoPaulo() } },\n  });\n}\n\n/**\n * Registra que a mensagem de reativacao foi aberta no WhatsApp para enviar.\n * A pessoa sai da lista e nunca mais recebe essa mensagem. Respeita o limite\n * do dia.\n */\nexport async function registrarEnvioReativacao(dados: { leadId: number; mensagem: string }) {\n  const usuario = await requirePermission(\"marketing.gerenciar\");\n  const leadId = Number(dados.leadId);\n\n  const [limite, jaHoje] = await Promise.all([limiteDiario(), enviadasHoje()]);\n  if (jaHoje >= limite) {\n    throw new Error(`Limite de hoje atingido (${jaHoje} de ${limite}). Continue amanhã para proteger o seu WhatsApp.`);\n  }\n\n  const agora = new Date();\n  await prisma.$transaction(async (tx) => {\n    const lead = await tx.lead.findUnique({\n      where: { id: leadId },\n      select: { id: true, nome: true, telefone: true, etapa: true, reativacaoEnviadaEm: true },\n    });\n    if (!lead) throw new Error(\"Lead não encontrado.\");\n    if (lead.reativacaoEnviadaEm) throw new Error(\"Esta pessoa já recebeu a mensagem de reativação.\");\n\n    // So marca se ainda nao foi marcado (evita contar duas vezes num clique duplo).\n    const marcado = await tx.lead.updateMany({\n      where: { id: leadId, reativacaoEnviadaEm: null },\n      data: { reativacaoEnviadaEm: agora, reativacaoResultado: null, reativacaoResultadoEm: null },\n    });\n    if (marcado.count === 0) throw new Error(\"Esta pessoa já recebeu a mensagem de reativação.\");\n\n    await tx.comunicacaoRegistro.create({\n      data: {\n        leadId,\n        destinatarioNome: lead.nome,\n        telefone: lead.telefone,\n        categoria: CATEGORIA_REATIVACAO_PERDIDOS,\n        canal: \"WhatsApp\",\n        mensagem: (dados.mensagem || \"\").trim().slice(0, 2000) || \"(mensagem de reativação)\",\n        status: \"Enviada\",\n        usuario: usuario.email,\n        abertoEm: agora,\n        enviadoEm: agora,\n      },\n    });\n\n    await tx.leadInteracao.create({\n      data: { leadId, tipo: \"Reativação\", descricao: \"Mensagem de reativação enviada pelo WhatsApp.\" },\n    });\n  });\n\n  revalidar();\n  return { ok: true as const, enviadasHoje: jaHoje + 1, limite };\n}\n\n/** \"Não consegui enviar\": desfaz o envio de HOJE (a pessoa volta para a lista). */\nexport async function desfazerEnvioReativacao(leadId: number) {\n  await requirePermission(\"marketing.gerenciar\");\n  const id = Number(leadId);\n  const inicio = inicioDoDiaSaoPaulo();\n\n  await prisma.$transaction(async (tx) => {\n    const lead = await tx.lead.findUnique({ where: { id }, select: { reativacaoEnviadaEm: true } });\n    if (!lead?.reativacaoEnviadaEm || lead.reativacaoEnviadaEm < inicio) {\n      throw new Error(\"Só dá para desfazer um envio feito hoje.\");\n    }\n    await tx.lead.update({\n      where: { id },\n      data: { reativacaoEnviadaEm: null, reativacaoResultado: null, reativacaoResultadoEm: null },\n    });\n    await tx.comunicacaoRegistro.deleteMany({\n      where: { leadId: id, categoria: CATEGORIA_REATIVACAO_PERDIDOS, enviadoEm: { gte: inicio } },\n    });\n    await tx.leadInteracao.create({\n      data: { leadId: id, tipo: \"Reativação\", descricao: \"Envio de reativação desfeito (a mensagem não foi enviada).\" },\n    });\n  });\n\n  revalidar();\n  return { ok: true as const };\n}\n\n/** Marca o que aconteceu depois da mensagem. \"Respondeu\" reabre o lead no funil. */\nexport async function registrarResultadoReativacao(dados: { leadId: number; resultado: ResultadoReativacao | null }) {\n  await requirePermission(\"marketing.gerenciar\");\n  const id = Number(dados.leadId);\n  const resultado = dados.resultado;\n  if (resultado && !(resultado in ROTULO_RESULTADO)) throw new Error(\"Resultado inválido.\");\n\n  const lead = await prisma.lead.findUnique({ where: { id }, select: { etapa: true, reativacaoEnviadaEm: true } });\n  if (!lead?.reativacaoEnviadaEm) throw new Error(\"Esta pessoa ainda não recebeu a reativação.\");\n\n  const reabrir = resultado === \"RESPONDEU\" && lead.etapa === \"Perdido\";\n  await prisma.$transaction([\n    prisma.lead.update({\n      where: { id },\n      data: {\n        reativacaoResultado: resultado,\n        reativacaoResultadoEm: resultado ? new Date() : null,\n        ...(reabrir ? { etapa: \"Aguardando resposta\", motivoPerda: null, proximoContatoEm: new Date() } : {}),\n      },\n    }),\n    prisma.leadInteracao.create({\n      data: {\n        leadId: id,\n        tipo: \"Reativação\",\n        descricao: resultado\n          ? `Resultado da reativação: ${ROTULO_RESULTADO[resultado]}.${reabrir ? \" Lead reaberto (Aguardando resposta).\" : \"\"}`\n          : \"Resultado da reativação apagado.\",\n      },\n    }),\n  ]);\n\n  revalidar();\n  return { ok: true as const };\n}\n\nexport async function definirLimiteDiarioReativacao(limite: number) {\n  await requirePermission(\"marketing.gerenciar\");\n  const valor = Math.min(LIMITE_MAXIMO, Math.max(LIMITE_MINIMO, Math.round(Number(limite) || 15)));\n  const atual = await prisma.configuracaoClinica.findFirst({ select: { id: true } });\n  if (atual) {\n    await prisma.configuracaoClinica.update({ where: { id: atual.id }, data: { reativacaoLimiteDiario: valor } });\n  } else {\n    await prisma.configuracaoClinica.create({ data: { reativacaoLimiteDiario: valor } });\n  }\n  revalidar();\n  return { ok: true as const, limite: valor };\n}\n\n/** Salva o texto-base de um servico (ou o padrao, com servico null). */\nexport async function salvarModeloReativacao(dados: { servico: string | null; texto: string }) {\n  await requirePermission(\"marketing.gerenciar\");\n  const texto = (dados.texto || \"\").trim();\n  if (texto.length < 10) throw new Error(\"Escreva a mensagem (pelo menos algumas palavras).\");\n  if (texto.length > 2000) throw new Error(\"A mensagem está muito longa.\");\n\n  const chave = chaveModeloDoServico(dados.servico);\n  const nome = dados.servico ? `Reativação · ${dados.servico}` : \"Reativação · padrão\";\n  await prisma.mensagemModelo.upsert({\n    where: { chave },\n    create: { chave, nome, categoria: CATEGORIA_REATIVACAO_PERDIDOS, corpo: texto, ativo: true },\n    update: { corpo: texto, nome },\n  });\n\n  revalidar();\n  return { ok: true as const };\n}\n","app/(app)/marketing/reativacao/page.tsx":"import { canAccess, requirePagePermission } from \"@/lib/auth\";\nimport { carregarReativacao, lerFiltros } from \"@/lib/reativacao-perdidos-dados\";\n\nimport ReativacaoClient from \"./components/ReativacaoClient\";\n\nexport const dynamic = \"force-dynamic\";\n\ntype Props = {\n  searchParams?: Promise<Record<string, string | undefined>> | Record<string, string | undefined>;\n};\n\nexport default async function ReativacaoPage({ searchParams }: Props) {\n  const usuario = await requirePagePermission(\"marketing.visualizar\");\n  const params = (await searchParams) ?? {};\n  const dados = await carregarReativacao(lerFiltros(params));\n\n  return <ReativacaoClient dados={dados} podeGerenciar={canAccess(usuario, \"marketing.gerenciar\")} />;\n}\n","app/(app)/marketing/reativacao/components/ReativacaoClient.tsx":"\"use client\";\n\nimport { useEffect, useMemo, useState, useTransition } from \"react\";\nimport Link from \"next/link\";\nimport { usePathname, useRouter, useSearchParams } from \"next/navigation\";\nimport {\n  ArrowLeft,\n  CheckCircle2,\n  ChevronLeft,\n  ChevronRight,\n  Hourglass,\n  Loader2,\n  MessageCircle,\n  PencilLine,\n  RotateCcw,\n  X,\n} from \"lucide-react\";\n\nimport {\n  definirLimiteDiarioReativacao,\n  desfazerEnvioReativacao,\n  registrarEnvioReativacao,\n  registrarResultadoReativacao,\n  salvarModeloReativacao,\n} from \"@/actions/reativacao-perdidos.actions\";\nimport type { DadosReativacao, ItemEnviado, ItemReativacao } from \"@/lib/reativacao-perdidos-dados\";\nimport {\n  PAUSA_ENTRE_ENVIOS_SEGUNDOS,\n  POR_PAGINA,\n  ROTULO_RESULTADO,\n  type ResultadoReativacao,\n} from \"@/lib/reativacao-perdidos\";\nimport { buildWhatsAppUrl } from \"@/lib/whatsapp\";\n\ntype Props = {\n  dados: DadosReativacao;\n  podeGerenciar: boolean;\n};\n\nconst OPCOES_DIAS = [\n  { valor: 0, rotulo: \"Qualquer data\" },\n  { valor: 30, rotulo: \"Último mês\" },\n  { valor: 60, rotulo: \"Últimos 2 meses\" },\n  { valor: 90, rotulo: \"Últimos 3 meses\" },\n  { valor: 180, rotulo: \"Últimos 6 meses\" },\n  { valor: 365, rotulo: \"Último ano\" },\n];\n\nconst OPCOES_LIMITE = [5, 10, 15, 20, 30];\n\nfunction dataCurta(valor: string | null) {\n  if (!valor) return \"-\";\n  return new Date(valor).toLocaleDateString(\"pt-BR\", { day: \"2-digit\", month: \"2-digit\", year: \"2-digit\", timeZone: \"America/Sao_Paulo\" });\n}\n\nfunction mensagemErro(erro: unknown) {\n  return erro instanceof Error && erro.message ? erro.message : \"Não foi possível salvar. Tente de novo.\";\n}\n\nconst campo =\n  \"h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-800 outline-none focus:border-violet-400 dark:border-white/10 dark:bg-slate-900 dark:text-slate-100\";\n\nexport default function ReativacaoClient({ dados, podeGerenciar }: Props) {\n  const router = useRouter();\n  const pathname = usePathname();\n  const parametros = useSearchParams();\n  const [pendente, iniciar] = useTransition();\n  const [erro, setErro] = useState(\"\");\n  const [enviadasHoje, setEnviadasHoje] = useState(dados.resumo.enviadasHoje);\n  const [ultimoEnvio, setUltimoEnvio] = useState<number>(() =>\n    dados.ultimoEnvioEm ? new Date(dados.ultimoEnvioEm).getTime() : 0,\n  );\n  const [agora, setAgora] = useState(() => Date.now());\n  const [enviadosAgora, setEnviadosAgora] = useState<number[]>([]);\n  const [editandoModelo, setEditandoModelo] = useState(false);\n\n  useEffect(() => {\n    const intervalo = window.setInterval(() => setAgora(Date.now()), 1000);\n    return () => window.clearInterval(intervalo);\n  }, []);\n\n  const limite = dados.limiteDiario;\n  const limiteAtingido = enviadasHoje >= limite;\n  const pausaRestante = Math.max(0, Math.ceil((ultimoEnvio + PAUSA_ENTRE_ENVIOS_SEGUNDOS * 1000 - agora) / 1000));\n  const { filtros } = dados;\n\n  function irPara(mudancas: Record<string, string | number | null>) {\n    const novo = new URLSearchParams(parametros.toString());\n    for (const [chave, valor] of Object.entries(mudancas)) {\n      if (valor === null || valor === \"\" || valor === 0) novo.delete(chave);\n      else novo.set(chave, String(valor));\n    }\n    if (!(\"pagina\" in mudancas)) novo.delete(\"pagina\");\n    router.push(`${pathname}?${novo.toString()}`);\n  }\n\n  function aoEnviar(item: ItemReativacao, mensagem: string) {\n    setErro(\"\");\n    setEnviadosAgora((atual) => [...atual, item.id]);\n    setEnviadasHoje((atual) => atual + 1);\n    setUltimoEnvio(Date.now());\n    registrarEnvioReativacao({ leadId: item.id, mensagem }).catch((e) => {\n      setEnviadosAgora((atual) => atual.filter((id) => id !== item.id));\n      setEnviadasHoje((atual) => Math.max(0, atual - 1));\n      setErro(mensagemErro(e));\n    });\n  }\n\n  function desfazer(item: ItemReativacao) {\n    setErro(\"\");\n    iniciar(async () => {\n      try {\n        await desfazerEnvioReativacao(item.id);\n        setEnviadosAgora((atual) => atual.filter((id) => id !== item.id));\n        setEnviadasHoje((atual) => Math.max(0, atual - 1));\n      } catch (e) {\n        setErro(mensagemErro(e));\n      }\n    });\n  }\n\n  function mudarLimite(valor: number) {\n    setErro(\"\");\n    iniciar(async () => {\n      try {\n        await definirLimiteDiarioReativacao(valor);\n        router.refresh();\n      } catch (e) {\n        setErro(mensagemErro(e));\n      }\n    });\n  }\n\n  const totalPaginas = Math.max(\n    1,\n    Math.ceil((filtros.aba === \"lista\" ? dados.totalLista : dados.totalEnviadas) / POR_PAGINA),\n  );\n\n  return (\n    <div className=\"app-mobile-safe space-y-4 pb-6 sm:space-y-5\">\n      <section className=\"rounded-2xl border border-slate-200 bg-white p-4 shadow-sm dark:border-white/10 dark:bg-white/[0.06] sm:rounded-3xl sm:p-6\">\n        <Link href=\"/marketing\" className=\"inline-flex items-center gap-1.5 text-xs font-semibold text-slate-500 hover:text-violet-700 dark:text-slate-400\">\n          <ArrowLeft size={14} /> Voltar para Marketing\n        </Link>\n        <h1 className=\"mt-3 text-xl font-bold tracking-tight text-slate-900 dark:text-white sm:text-3xl\">Reativação de perdidos</h1>\n        <p className=\"mt-2 max-w-3xl text-sm leading-6 text-slate-600 dark:text-slate-400\">\n          Quem procurou e não fechou. Cada pessoa recebe a mensagem uma vez só: depois de enviar, ela sai da lista.\n          Mande aos poucos, dentro do limite do dia, para o WhatsApp não entender como spam.\n        </p>\n\n        <div className=\"mt-4 grid grid-cols-3 gap-2 sm:grid-cols-[1.4fr_1fr_1fr_1fr] sm:gap-3\">\n          <div className={`col-span-3 rounded-2xl border p-3 sm:col-span-1 ${limiteAtingido ? \"border-rose-200 bg-rose-50 dark:border-rose-400/20 dark:bg-rose-500/10\" : \"border-emerald-200 bg-emerald-50 dark:border-emerald-400/20 dark:bg-emerald-500/10\"}`}>\n            <p className=\"text-xs font-semibold text-slate-600 dark:text-slate-300\">Hoje você enviou</p>\n            <p className={`text-2xl font-bold ${limiteAtingido ? \"text-rose-700 dark:text-rose-300\" : \"text-emerald-700 dark:text-emerald-300\"}`}>\n              {enviadasHoje} <span className=\"text-base font-semibold text-slate-500\">de {limite}</span>\n            </p>\n            <div className=\"mt-2 h-2 overflow-hidden rounded-full bg-white/70 dark:bg-white/10\">\n              <div\n                className={`h-full rounded-full ${limiteAtingido ? \"bg-rose-500\" : \"bg-emerald-500\"}`}\n                style={{ width: `${Math.min(100, (enviadasHoje / Math.max(1, limite)) * 100)}%` }}\n              />\n            </div>\n            {podeGerenciar ? (\n              <label className=\"mt-2 flex items-center gap-2 text-xs text-slate-600 dark:text-slate-300\">\n                Limite por dia\n                <select\n                  value={OPCOES_LIMITE.includes(limite) ? limite : \"\"}\n                  onChange={(evento) => mudarLimite(Number(evento.target.value))}\n                  disabled={pendente}\n                  className=\"h-8 rounded-lg border border-slate-200 bg-white px-2 text-xs dark:border-white/10 dark:bg-slate-900\"\n                >\n                  {!OPCOES_LIMITE.includes(limite) ? <option value=\"\">{limite}</option> : null}\n                  {OPCOES_LIMITE.map((opcao) => (\n                    <option key={opcao} value={opcao}>\n                      {opcao}\n                    </option>\n                  ))}\n                </select>\n              </label>\n            ) : null}\n          </div>\n          <Resumo rotulo=\"Já enviadas\" valor={dados.resumo.enviadas} />\n          <Resumo rotulo=\"Responderam\" valor={dados.resumo.responderam} />\n          <Resumo rotulo=\"Voltaram / agendaram\" valor={dados.resumo.voltaram} destaque />\n        </div>\n      </section>\n\n      <div className=\"flex gap-2\">\n        <button\n          type=\"button\"\n          onClick={() => irPara({ aba: null })}\n          className={`h-10 rounded-xl px-4 text-sm font-bold ${filtros.aba === \"lista\" ? \"bg-violet-600 text-white\" : \"border border-slate-200 bg-white text-slate-700 dark:border-white/10 dark:bg-transparent dark:text-slate-200\"}`}\n        >\n          Para reativar ({dados.totalLista})\n        </button>\n        <button\n          type=\"button\"\n          onClick={() => irPara({ aba: \"enviadas\" })}\n          className={`h-10 rounded-xl px-4 text-sm font-bold ${filtros.aba === \"enviadas\" ? \"bg-violet-600 text-white\" : \"border border-slate-200 bg-white text-slate-700 dark:border-white/10 dark:bg-transparent dark:text-slate-200\"}`}\n        >\n          Já enviadas ({dados.totalEnviadas})\n        </button>\n      </div>\n\n      {erro ? <p className=\"rounded-2xl border border-rose-200 bg-rose-50 px-3 py-2 text-sm font-semibold text-rose-700\">{erro}</p> : null}\n\n      {filtros.aba === \"lista\" ? (\n        <>\n          <section className=\"grid gap-2 rounded-2xl border border-slate-200 bg-white p-3 shadow-sm dark:border-white/10 dark:bg-white/[0.04] sm:grid-cols-[1.3fr_1fr_1fr_auto] sm:items-end\">\n            <label className=\"grid gap-1 text-xs font-semibold text-slate-600 dark:text-slate-300\">\n              Serviço que procurou\n              <select value={filtros.servico} onChange={(evento) => irPara({ servico: evento.target.value })} className={campo}>\n                <option value=\"\">Todos os serviços</option>\n                {dados.servicos.map((item) => (\n                  <option key={item.nome} value={item.nome}>\n                    {item.nome} ({item.quantidade})\n                  </option>\n                ))}\n              </select>\n            </label>\n            <label className=\"grid gap-1 text-xs font-semibold text-slate-600 dark:text-slate-300\">\n              Perdido em\n              <select value={filtros.dias} onChange={(evento) => irPara({ dias: Number(evento.target.value) })} className={campo}>\n                {OPCOES_DIAS.map((opcao) => (\n                  <option key={opcao.valor} value={opcao.valor}>\n                    {opcao.rotulo}\n                  </option>\n                ))}\n              </select>\n            </label>\n            <label className=\"grid gap-1 text-xs font-semibold text-slate-600 dark:text-slate-300\">\n              Origem\n              <select value={filtros.origem} onChange={(evento) => irPara({ origem: evento.target.value })} className={campo}>\n                <option value=\"\">Todas</option>\n                {dados.origens.map((item) => (\n                  <option key={item.nome} value={item.nome}>\n                    {item.nome} ({item.quantidade})\n                  </option>\n                ))}\n              </select>\n            </label>\n            {podeGerenciar ? (\n              <button\n                type=\"button\"\n                onClick={() => setEditandoModelo(true)}\n                className=\"inline-flex h-11 items-center justify-center gap-2 rounded-xl border border-violet-200 bg-violet-50 px-3 text-sm font-semibold text-violet-700 hover:bg-violet-100 dark:border-violet-400/20 dark:bg-violet-500/10 dark:text-violet-200\"\n              >\n                <PencilLine size={16} /> Textos\n              </button>\n            ) : null}\n          </section>\n\n          {limiteAtingido ? (\n            <p className=\"rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm font-semibold text-rose-800 dark:border-rose-400/20 dark:bg-rose-500/10 dark:text-rose-200\">\n              Limite de hoje atingido ({enviadasHoje} de {limite}). Continue amanhã: mandar muitas mensagens no mesmo dia pode bloquear o número.\n            </p>\n          ) : pausaRestante > 0 ? (\n            <p className=\"flex items-center gap-2 rounded-2xl border border-amber-200 bg-amber-50 px-4 py-2 text-sm font-semibold text-amber-800 dark:border-amber-400/20 dark:bg-amber-500/10 dark:text-amber-200\">\n              <Hourglass size={16} /> Próximo envio liberado em {pausaRestante}s (uma pausa entre as mensagens ajuda a não parecer disparo em massa).\n            </p>\n          ) : null}\n\n          {dados.itens.length === 0 ? (\n            <div className=\"rounded-2xl border border-dashed border-emerald-200 bg-emerald-50/70 p-8 text-center dark:border-emerald-400/20 dark:bg-emerald-500/10\">\n              <CheckCircle2 className=\"mx-auto size-7 text-emerald-600\" />\n              <p className=\"mt-3 text-sm font-semibold text-emerald-900 dark:text-emerald-200\">Ninguém para reativar com esses filtros.</p>\n            </div>\n          ) : (\n            <div className=\"space-y-2.5\">\n              {dados.itens.map((item) => (\n                <CartaoPerdido\n                  key={item.id}\n                  item={item}\n                  enviado={enviadosAgora.includes(item.id)}\n                  bloqueado={!podeGerenciar || limiteAtingido || pausaRestante > 0}\n                  pendente={pendente}\n                  onEnviar={aoEnviar}\n                  onDesfazer={desfazer}\n                />\n              ))}\n            </div>\n          )}\n        </>\n      ) : (\n        <ListaEnviadas itens={dados.enviadas} podeGerenciar={podeGerenciar} onErro={setErro} />\n      )}\n\n      {totalPaginas > 1 ? (\n        <div className=\"flex items-center justify-center gap-3 text-sm\">\n          <button\n            type=\"button\"\n            disabled={filtros.pagina <= 1}\n            onClick={() => irPara({ pagina: filtros.pagina - 1 })}\n            className=\"inline-flex h-10 items-center gap-1 rounded-xl border border-slate-200 bg-white px-3 font-semibold disabled:opacity-40 dark:border-white/10 dark:bg-transparent\"\n          >\n            <ChevronLeft size={16} /> Anterior\n          </button>\n          <span className=\"text-slate-600 dark:text-slate-300\">\n            Página {filtros.pagina} de {totalPaginas}\n          </span>\n          <button\n            type=\"button\"\n            disabled={filtros.pagina >= totalPaginas}\n            onClick={() => irPara({ pagina: filtros.pagina + 1 })}\n            className=\"inline-flex h-10 items-center gap-1 rounded-xl border border-slate-200 bg-white px-3 font-semibold disabled:opacity-40 dark:border-white/10 dark:bg-transparent\"\n          >\n            Próxima <ChevronRight size={16} />\n          </button>\n        </div>\n      ) : null}\n\n      {editandoModelo ? (\n        <EditorModelos\n          modelos={dados.modelos}\n          servicoInicial={filtros.servico || null}\n          onFechar={() => setEditandoModelo(false)}\n        />\n      ) : null}\n    </div>\n  );\n}\n\nfunction Resumo({ rotulo, valor, destaque = false }: { rotulo: string; valor: number; destaque?: boolean }) {\n  return (\n    <div className=\"rounded-2xl border border-slate-200 bg-slate-50 p-2.5 dark:border-white/10 dark:bg-white/[0.04] sm:p-3\">\n      <p className=\"text-[11px] font-semibold leading-4 text-slate-600 dark:text-slate-300 sm:text-xs\">{rotulo}</p>\n      <p className={`text-xl font-bold sm:text-2xl ${destaque ? \"text-violet-700 dark:text-violet-300\" : \"text-slate-900 dark:text-white\"}`}>{valor}</p>\n    </div>\n  );\n}\n\nfunction CartaoPerdido({\n  item,\n  enviado,\n  bloqueado,\n  pendente,\n  onEnviar,\n  onDesfazer,\n}: {\n  item: ItemReativacao;\n  enviado: boolean;\n  bloqueado: boolean;\n  pendente: boolean;\n  onEnviar: (item: ItemReativacao, mensagem: string) => void;\n  onDesfazer: (item: ItemReativacao) => void;\n}) {\n  const [mensagem, setMensagem] = useState(item.mensagem);\n  const [editando, setEditando] = useState(false);\n  const url = useMemo(() => buildWhatsAppUrl(item.telefone, mensagem), [item.telefone, mensagem]);\n  const travado = bloqueado || item.jaRecebeuPorOutroCadastro || !item.telefone;\n\n  return (\n    <div\n      className={`rounded-2xl border bg-white p-4 shadow-sm transition dark:bg-white/[0.04] ${\n        enviado ? \"border-slate-200 opacity-70 dark:border-white/10\" : \"border-violet-200 dark:border-violet-400/25\"\n      }`}\n    >\n      <div className=\"flex flex-wrap items-start justify-between gap-2\">\n        <div className=\"min-w-0\">\n          <p className=\"break-words font-semibold text-slate-900 dark:text-white\">{item.nome}</p>\n          <p className=\"mt-0.5 text-xs text-slate-500 dark:text-slate-400\">\n            {item.servico || \"Serviço não informado\"} · {item.origem || \"sem origem\"} · perdido em {dataCurta(item.perdidoEm)}\n          </p>\n          {item.motivoPerda ? <p className=\"mt-0.5 text-xs text-slate-500 dark:text-slate-400\">Motivo: {item.motivoPerda}</p> : null}\n        </div>\n        {enviado ? (\n          <span className=\"inline-flex items-center gap-1 rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-bold text-emerald-700\">\n            <CheckCircle2 size={14} /> Enviada\n          </span>\n        ) : null}\n      </div>\n\n      {editando && !enviado ? (\n        <textarea\n          value={mensagem}\n          onChange={(evento) => setMensagem(evento.target.value)}\n          rows={6}\n          className=\"mt-3 w-full rounded-xl border border-slate-200 bg-white p-3 text-sm leading-6 text-slate-800 outline-none focus:border-violet-400 dark:border-white/10 dark:bg-slate-900 dark:text-slate-100\"\n        />\n      ) : (\n        <div className=\"mt-3 rounded-xl bg-slate-50 p-3 text-sm leading-6 text-slate-700 dark:bg-white/[0.04] dark:text-slate-300\">\n          <p className=\"line-clamp-3 whitespace-pre-line\">{mensagem}</p>\n        </div>\n      )}\n\n      {item.jaRecebeuPorOutroCadastro && !enviado ? (\n        <p className=\"mt-2 text-xs font-semibold text-amber-700 dark:text-amber-300\">\n          Este telefone já recebeu a reativação por outro cadastro. Não será enviado de novo.\n        </p>\n      ) : null}\n\n      <div className=\"mt-3 flex flex-wrap gap-2\">\n        {enviado ? (\n          <button\n            type=\"button\"\n            onClick={() => onDesfazer(item)}\n            disabled={pendente}\n            className=\"inline-flex min-h-10 items-center gap-1.5 rounded-xl border border-slate-200 px-3 text-xs font-semibold text-slate-600 hover:bg-slate-50 disabled:opacity-50 dark:border-white/10 dark:text-slate-300\"\n          >\n            {pendente ? <Loader2 size={14} className=\"animate-spin\" /> : <RotateCcw size={14} />}\n            Não consegui enviar (desfazer)\n          </button>\n        ) : (\n          <>\n            {travado ? (\n              <span className=\"inline-flex min-h-10 flex-1 items-center justify-center gap-2 rounded-xl bg-slate-100 px-3 text-xs font-semibold text-slate-400 dark:bg-white/[0.06]\">\n                <MessageCircle className=\"size-4\" /> Enviar no WhatsApp\n              </span>\n            ) : (\n              <a\n                href={url}\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                onClick={() => onEnviar(item, mensagem)}\n                className=\"inline-flex min-h-10 flex-1 items-center justify-center gap-2 rounded-xl bg-emerald-600 px-3 text-xs font-bold text-white hover:bg-emerald-700\"\n              >\n                <MessageCircle className=\"size-4\" /> Enviar no WhatsApp\n              </a>\n            )}\n            <button\n              type=\"button\"\n              onClick={() => setEditando((atual) => !atual)}\n              className=\"inline-flex min-h-10 items-center gap-1.5 rounded-xl border border-slate-200 px-3 text-xs font-semibold text-slate-600 hover:bg-slate-50 dark:border-white/10 dark:text-slate-300\"\n            >\n              <PencilLine size={14} /> {editando ? \"Pronto\" : \"Editar texto\"}\n            </button>\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n\nfunction ListaEnviadas({\n  itens,\n  podeGerenciar,\n  onErro,\n}: {\n  itens: ItemEnviado[];\n  podeGerenciar: boolean;\n  onErro: (texto: string) => void;\n}) {\n  const router = useRouter();\n  const [pendente, iniciar] = useTransition();\n\n  function marcar(item: ItemEnviado, resultado: ResultadoReativacao) {\n    onErro(\"\");\n    iniciar(async () => {\n      try {\n        await registrarResultadoReativacao({ leadId: item.id, resultado: item.resultado === resultado ? null : resultado });\n        router.refresh();\n      } catch (e) {\n        onErro(mensagemErro(e));\n      }\n    });\n  }\n\n  if (itens.length === 0) {\n    return (\n      <p className=\"rounded-2xl border border-dashed border-slate-200 bg-white p-8 text-center text-sm text-slate-500 dark:border-white/10 dark:bg-white/[0.04]\">\n        Nenhuma reativação enviada ainda.\n      </p>\n    );\n  }\n\n  return (\n    <div className=\"space-y-2\">\n      {itens.map((item) => (\n        <div key={item.id} className=\"rounded-2xl border border-slate-200 bg-white p-3 shadow-sm dark:border-white/10 dark:bg-white/[0.04]\">\n          <div className=\"flex flex-wrap items-start justify-between gap-2\">\n            <div className=\"min-w-0\">\n              <p className=\"break-words font-semibold text-slate-900 dark:text-white\">{item.nome}</p>\n              <p className=\"text-xs text-slate-500 dark:text-slate-400\">\n                {item.servico || \"Serviço não informado\"} · enviada em {dataCurta(item.enviadaEm)}\n              </p>\n            </div>\n            {item.agendouSozinho ? (\n              <span className=\"rounded-full bg-violet-50 px-2.5 py-1 text-xs font-bold text-violet-700\">Voltou: tem agendamento depois da mensagem</span>\n            ) : item.resultado ? (\n              <span className=\"rounded-full bg-slate-100 px-2.5 py-1 text-xs font-bold text-slate-700 dark:bg-white/10 dark:text-slate-200\">\n                {ROTULO_RESULTADO[item.resultado]}\n              </span>\n            ) : null}\n          </div>\n          {podeGerenciar ? (\n            <div className=\"mt-2 flex flex-wrap gap-1.5\">\n              {(Object.keys(ROTULO_RESULTADO) as ResultadoReativacao[]).map((resultado) => (\n                <button\n                  key={resultado}\n                  type=\"button\"\n                  disabled={pendente}\n                  onClick={() => marcar(item, resultado)}\n                  aria-pressed={item.resultado === resultado}\n                  className={`h-8 rounded-lg px-2.5 text-xs font-semibold disabled:opacity-50 ${\n                    item.resultado === resultado\n                      ? \"bg-violet-600 text-white\"\n                      : \"border border-slate-200 text-slate-600 hover:bg-slate-50 dark:border-white/10 dark:text-slate-300\"\n                  }`}\n                >\n                  {ROTULO_RESULTADO[resultado]}\n                </button>\n              ))}\n            </div>\n          ) : null}\n        </div>\n      ))}\n    </div>\n  );\n}\n\nfunction EditorModelos({\n  modelos,\n  servicoInicial,\n  onFechar,\n}: {\n  modelos: DadosReativacao[\"modelos\"];\n  servicoInicial: string | null;\n  onFechar: () => void;\n}) {\n  const router = useRouter();\n  const [pendente, iniciar] = useTransition();\n  const inicial = modelos.find((item) => item.servico === servicoInicial) ?? modelos[0];\n  const [chave, setChave] = useState(inicial?.chave ?? \"\");\n  const atual = modelos.find((item) => item.chave === chave) ?? inicial;\n  const [texto, setTexto] = useState(atual?.texto ?? \"\");\n  const [erro, setErro] = useState(\"\");\n\n  function trocar(novaChave: string) {\n    setChave(novaChave);\n    setTexto(modelos.find((item) => item.chave === novaChave)?.texto ?? \"\");\n  }\n\n  function salvar() {\n    setErro(\"\");\n    iniciar(async () => {\n      try {\n        await salvarModeloReativacao({ servico: atual?.servico ?? null, texto });\n        router.refresh();\n        onFechar();\n      } catch (e) {\n        setErro(mensagemErro(e));\n      }\n    });\n  }\n\n  return (\n    <div className=\"fixed inset-0 z-[120] flex items-end justify-center bg-slate-950/55 p-0 backdrop-blur-sm sm:items-center sm:p-4\">\n      <div className=\"flex max-h-[92dvh] w-full max-w-xl flex-col overflow-hidden rounded-t-3xl bg-white shadow-2xl sm:rounded-3xl dark:bg-slate-900\">\n        <header className=\"flex items-start justify-between gap-3 border-b border-slate-100 px-4 py-3 dark:border-white/10\">\n          <div>\n            <p className=\"font-bold text-slate-900 dark:text-white\">Texto da mensagem por serviço</p>\n            <p className=\"text-xs text-slate-500 dark:text-slate-400\">\n              Use {\"{nome}\"} para o primeiro nome e {\"{servico}\"} para o serviço que a pessoa procurou.\n            </p>\n          </div>\n          <button type=\"button\" onClick={onFechar} aria-label=\"Fechar\" className=\"rounded-xl border border-slate-200 p-2 text-slate-500 dark:border-white/10\">\n            <X size={16} />\n          </button>\n        </header>\n        <div className=\"space-y-3 overflow-y-auto px-4 py-4\">\n          <label className=\"grid gap-1 text-xs font-semibold text-slate-600 dark:text-slate-300\">\n            Serviço\n            <select value={chave} onChange={(evento) => trocar(evento.target.value)} className={campo}>\n              {modelos.map((item) => (\n                <option key={item.chave} value={item.chave}>\n                  {item.servico ?? \"Padrão (serviços sem texto próprio)\"}\n                  {item.personalizado ? \" · editado\" : \"\"}\n                </option>\n              ))}\n            </select>\n          </label>\n          <textarea\n            value={texto}\n            onChange={(evento) => setTexto(evento.target.value)}\n            rows={9}\n            className=\"w-full rounded-xl border border-slate-200 bg-white p-3 text-sm leading-6 text-slate-800 outline-none focus:border-violet-400 dark:border-white/10 dark:bg-slate-950 dark:text-slate-100\"\n          />\n          {erro ? <p className=\"rounded-xl bg-rose-50 px-3 py-2 text-sm font-semibold text-rose-700\">{erro}</p> : null}\n        </div>\n        <footer className=\"flex gap-2 border-t border-slate-100 px-4 py-3 dark:border-white/10\">\n          <button type=\"button\" onClick={onFechar} className=\"h-11 flex-1 rounded-xl border border-slate-200 text-sm font-semibold dark:border-white/10 dark:text-slate-200\">\n            Cancelar\n          </button>\n          <button\n            type=\"button\"\n            onClick={salvar}\n            disabled={pendente}\n            className=\"inline-flex h-11 flex-[2] items-center justify-center gap-2 rounded-xl bg-violet-600 text-sm font-bold text-white disabled:opacity-50\"\n          >\n            {pendente ? <Loader2 size={16} className=\"animate-spin\" /> : null}\n            Salvar texto\n          </button>\n        </footer>\n      </div>\n    </div>\n  );\n}\n","prisma/migrations/20261020190000_reativacao_perdidos/migration.sql":"-- Reativacao de leads perdidos: data da perda, envio (uma vez so) e resultado.\nALTER TABLE \"Lead\" ADD COLUMN \"perdidoEm\" TIMESTAMP(3);\nALTER TABLE \"Lead\" ADD COLUMN \"reativacaoEnviadaEm\" TIMESTAMP(3);\nALTER TABLE \"Lead\" ADD COLUMN \"reativacaoResultado\" TEXT;\nALTER TABLE \"Lead\" ADD COLUMN \"reativacaoResultadoEm\" TIMESTAMP(3);\n\nCREATE INDEX \"Lead_etapa_reativacaoEnviadaEm_perdidoEm_idx\" ON \"Lead\"(\"etapa\", \"reativacaoEnviadaEm\", \"perdidoEm\");\nCREATE INDEX \"Lead_reativacaoEnviadaEm_idx\" ON \"Lead\"(\"reativacaoEnviadaEm\");\n\nALTER TABLE \"ConfiguracaoClinica\" ADD COLUMN \"reativacaoLimiteDiario\" INTEGER NOT NULL DEFAULT 15;\n\n-- Leads que ja estavam perdidos: a data da perda vem do historico (\"Perda\");\n-- sem historico, usa a ultima atualizacao do lead.\nUPDATE \"Lead\" l\nSET \"perdidoEm\" = COALESCE(\n  (SELECT MAX(i.\"createdAt\") FROM \"LeadInteracao\" i WHERE i.\"leadId\" = l.\"id\" AND i.\"tipo\" = 'Perda'),\n  l.\"updatedAt\"\n)\nWHERE l.\"etapa\" = 'Perdido' AND l.\"perdidoEm\" IS NULL;\n"},"arquivos":[{"arquivo":"prisma/schema.prisma","obrigatorio":true,"patches":[{"nome":"ajuste 1","antes":"  // \"Nao e esse clique\": nao sugerir mais clique para este contato.\n  sugestaoCliqueRecusada Boolean @default(false)","depois":"  // \"Nao e esse clique\": nao sugerir mais clique para este contato.\n  sugestaoCliqueRecusada Boolean @default(false)\n  // Reativacao de perdidos: quando virou Perdido, quando recebeu a mensagem\n  // de reativacao (uma vez so) e o que aconteceu depois.\n  perdidoEm             DateTime?\n  reativacaoEnviadaEm   DateTime?\n  reativacaoResultado   String?\n  reativacaoResultadoEm DateTime?"},{"nome":"ajuste 2","antes":"  @@index([gclid])\n  @@index([origem])\n}","depois":"  @@index([gclid])\n  @@index([origem])\n  @@index([etapa, reativacaoEnviadaEm, perdidoEm])\n  @@index([reativacaoEnviadaEm])\n}"},{"nome":"ajuste 3","antes":"  googleAdsPorProcedimento Boolean @default(false)","depois":"  googleAdsPorProcedimento Boolean @default(false)\n  // Reativacao de perdidos: quantas mensagens por dia (protege o numero).\n  reativacaoLimiteDiario Int @default(15)"}]},{"arquivo":"actions/marketing.actions.ts","obrigatorio":true,"patches":[{"nome":"ajuste 1","antes":"        etapa: \"Perdido\",\n        motivoPerda: motivoLimpo,\n        proximoContatoEm: null,","depois":"        etapa: \"Perdido\",\n        motivoPerda: motivoLimpo,\n        proximoContatoEm: null,\n        perdidoEm: new Date(),"}]},{"arquivo":"app/(app)/marketing/components/MarketingClient.tsx","obrigatorio":true,"patches":[{"nome":"ajuste 1","antes":"                Gasto Google Ads\n              </Link>","depois":"                Gasto Google Ads\n              </Link>\n              <Link\n                href=\"/marketing/reativacao\"\n                className=\"inline-flex h-10 items-center justify-center gap-2 rounded-xl border border-violet-200 bg-violet-50 px-4 text-sm font-semibold text-violet-700 shadow-sm hover:border-violet-300 hover:bg-violet-100\"\n              >\n                Reativar perdidos\n              </Link>"}]}]};
const raiz = process.cwd();
const aGravar = [];
let erros = 0;
let avisos = 0;

for (const [relativo, conteudo] of Object.entries(DATA.novosArquivos)) {
  const caminho = path.join(raiz, ...relativo.split("/"));
  const existente = fs.existsSync(caminho) ? fs.readFileSync(caminho, "utf8").replace(/\r\n/g, "\n") : null;
  if (existente === conteudo) {
    console.log("[pulou] " + relativo + " - ja existe igual");
  } else {
    aGravar.push({ caminho, conteudo, pasta: true });
    console.log((existente === null ? "[ok] criar " : "[ok] atualizar ") + relativo);
  }
}

for (const arq of DATA.arquivos) {
  const caminho = path.join(raiz, ...arq.arquivo.split("/"));
  if (!fs.existsSync(caminho)) {
    if (arq.obrigatorio) { console.log("[erro] arquivo nao encontrado: " + arq.arquivo + ". Rode na pasta do projeto."); erros++; }
    else { console.log("[aviso] arquivo nao encontrado, mantido: " + arq.arquivo); avisos++; }
    continue;
  }
  const bruto = fs.readFileSync(caminho, "utf8");
  const crlf = bruto.includes("\r\n");
  let texto = bruto.replace(/\r\n/g, "\n");
  let mudou = false;

  for (const p of arq.patches) {
    const ocorrencias = texto.split(p.antes).length - 1;
    if (p.modo === "remover") {
      // trecho a ser tirado: se ainda existe, tira; se nao existe, ja foi feito
      if (ocorrencias === 1) {
        texto = texto.replace(p.antes, () => p.depois);
        mudou = true;
        console.log("[ok] " + p.nome + " (" + arq.arquivo + ")");
      } else if (ocorrencias === 0) {
        console.log("[pulou] " + p.nome + " (" + arq.arquivo + ") - ja feito ou trecho diferente");
      } else {
        console.log("[aviso] " + p.nome + " (" + arq.arquivo + ") - aparece mais de uma vez, mantido");
        avisos++;
      }
      continue;
    }
    if (texto.includes(p.depois)) {
      console.log("[pulou] " + p.nome + " (" + arq.arquivo + ") - ja aplicado");
    } else if (ocorrencias === 1) {
      texto = texto.replace(p.antes, () => p.depois);
      mudou = true;
      console.log("[ok] " + p.nome + " (" + arq.arquivo + ")");
    } else {
      console.log("[erro] " + p.nome + " (" + arq.arquivo + ") - trecho nao encontrado");
      erros++;
    }
  }
  if (mudou) aGravar.push({ caminho, conteudo: crlf ? texto.replace(/\n/g, "\r\n") : texto });
}

if (erros > 0) {
  console.log("\nNada foi gravado: " + erros + " problema(s). Me mande esta tela.");
  process.exit(1);
}
for (const g of aGravar) {
  if (g.pasta) fs.mkdirSync(path.dirname(g.caminho), { recursive: true });
  fs.writeFileSync(g.caminho, g.conteudo, "utf8");
}
if (avisos > 0) console.log("\n" + avisos + " aviso(s): trechos opcionais que ficaram como estavam (nada quebra).");
console.log("\nConcluido.");
